import { startLoomTutorial, LOOM_TUTORIAL } from "./loom-tutorial.mjs";
import {
  refreshBossPlans,
  resolveBile,
  phasePlan,
  disrupt,
  antiElement,
} from "./loom-bosses.mjs";
import { STRATA } from "./strata.mjs";
import {
  canEnter,
  repairTargets,
  mend,
  corruptionAt,
  corruptionPower,
  resetCoveredInsanity,
  prepareCorruption,
  retargetCoveredCorruptions,
  applyCorruptions,
  startRepairs,
  corruptionRound,
  triggerAnger,
} from "./corruptions.mjs";
import {
  SATCHEL_CAPACITY,
  satchelContents,
  consumableReason,
} from "./consumables.mjs";
import {
  tutorialActions,
  normalizeTutorial,
  tutorialAfter,
  tutorialGuide,
  tutorialBattle,
  tutorialBattleReady,
  tutorialDrawIndex,
  tutorialReward,
  tutorialTavern,
} from "./tutorial.mjs";
import { describeDeath } from "./death.mjs";
import {
  cards,
  CARD_BUY_PRICES,
  gemServiceCost,
  TRAVELER_DONATION,
  items,
  enemies,
  events,
  starter,
  ELEMENTS,
  ENEMY_STATUS_IMMUNITY,
  cycle,
  VERSION,
  EARLY_MOTES,
  MIND_COLUMNS,
  MIND_ROWS,
  MIND_SIZE,
} from "./content.mjs";
export const clone = (x) => structuredClone(x);
const excludedStarterOffers = new Set(starter.filter((id) => id !== "focus"));
export const enemyStatusImmunity = (e) =>
  ENEMY_STATUS_IMMUNITY[e.element] || null;
export const enemyStatusImmunities = (e) => [
  ...new Set([
    ...(enemies[e.id]?.statusImmunities || []),
    ...[enemyStatusImmunity(e)].filter(Boolean),
  ]),
];
export const enemyImmuneTo = (e, status) =>
  enemyStatusImmunities(e).includes(status);
function clearImmuneStatus(e) {
  const cleared = enemyStatusImmunities(e).filter(
    (status) => e.status?.[status],
  );
  for (const status of cleared) e.status[status] = 0;
  return cleared.length ? cleared.map(statusName).join(" and ") : null;
}
function normalizeEnemyImmunities(state) {
  for (const e of state.battle?.enemies || []) clearImmuneStatus(e);
  if (state.checkpoint) normalizeEnemyImmunities(state.checkpoint);
}
const statusName = (k) => k[0].toUpperCase() + k.slice(1);
export function elementalRate(from, to) {
  return from === "Arcane" || to === "Arcane"
    ? 1
    : cycle[from] === to
      ? 1.5
      : cycle[to] === from
        ? 0.5
        : 1;
}
export function offense(n, from, to) {
  return Math.ceil(n * elementalRate(from, to));
}
export function gridNeighbors(b, i) {
  if (top(b.grid[i])?.sever) return [];
  return adjacent(i).filter((j) => top(b.grid[j]) && !top(b.grid[j]).sever);
}
// A relay changes only the element offered for Attune, never printed-element conditions.
export function attunementSourceElement(b, c) {
  const d = cards[c.id];
  if (c.transmuted || c.element !== d.element) return c.element;
  return d.attune && c.lastActivatedTurn === b.turn
    ? c.lastActivationElement || c.element
    : c.element;
}
export function attunementElements(b, c, i) {
  const d = cards[c.id];
  const elements =
    d.attune && !c.transmuted && c.element === d.element
      ? [
          "Arcane",
          ...new Set(
            gridNeighbors(b, i)
              .map((j) => attunementSourceElement(b, top(b.grid[j])))
              .filter((element) => element !== "Arcane"),
          ),
        ]
      : [c.element];
  return elements.length ? elements : ["Arcane"];
}
export function conduitActive(b, c) {
  return !!(c && cards[c.id].effects.conduit && c.lastActivatedTurn === b.turn);
}
export function defensiveElement(b, c) {
  return conduitActive(b, c) ? attunementSourceElement(b, c) : c.element;
}
export function matchingNeighborSlots(b, c, i) {
  if (c.sever || top(b.grid[i])?.uid !== c.uid) return [];
  return gridNeighbors(b, i).filter((j) => {
    const other = top(b.grid[j]);
    return (
      other.id === c.id ||
      (["blast", "shield"].includes(c.id) && conduitActive(b, other))
    );
  });
}
export function chargeSources(b, c, i) {
  const element = cards[c.id].chargeElement;
  return element
    ? gridNeighbors(b, i).filter(
        (j) => attunementSourceElement(b, top(b.grid[j])) === element,
      )
    : [];
}
export function chargeGain(b, c, i) {
  const d = cards[c.id];
  return Math.min(
    Math.max(0, (d.charge || 0) - (c.charge || 0)),
    chargeSources(b, c, i).length ? 2 : 1,
  );
}
export function chargeActivations(b, c, i) {
  const d = cards[c.id];
  if (!d.charge || c.charge >= d.charge) return 1;
  return Math.ceil((d.charge - (c.charge || 0)) / chargeGain(b, c, i)) + 1;
}
function normalizeCharges(state) {
  for (const c of state.battle?.grid?.flat() || []) {
    const required = cards[c.id]?.charge;
    if (required) c.charge = Math.min(required, Math.max(0, c.charge || 0));
  }
  if (state.checkpoint) normalizeCharges(state.checkpoint);
}
export function matchingNeighbors(b, c, i) {
  return matchingNeighborSlots(b, c, i).length;
}
// Shared by resolution, UI and policy; added HP never enters the current attack.
export function activationGrowth(b, c, i) {
  const d = cards[c.id];
  if (c.sever || top(b.grid[i])?.uid !== c.uid) return 0;
  return Math.max(
    0,
    Math.min(
      (d.effects.growAfterAttack || 0) * gridNeighbors(b, i).length,
      (d.hpCap ?? Infinity) - c.hp,
    ),
  );
}
function capAllyHP(c) {
  const cap = cards[c.id]?.hpCap;
  if (cap != null) {
    c.hp = Math.min(c.hp, cap);
    c.maxHp = cap;
  }
  return c;
}
function normalizeCardCaps(state) {
  for (const c of state.battle?.grid?.flat() || []) capAllyHP(c);
  if (state.checkpoint) normalizeCardCaps(state.checkpoint);
}
export function enemyDamage(n, element, enemy) {
  let damage = offense(n, element, enemy.element);
  if (enemy.resist === element) damage = Math.ceil(damage / 2);
  if (enemy.wisp) damage = Math.ceil(damage * (element === "Arcane" ? 0.5 : 2));
  return damage;
}
// Shared by damage and its visual indicator; first valid block wins (no stacking).
export function squarePattern(b, c, i) {
  if (c.sever) return [];
  for (const origin of [i, i - 1, i - MIND_COLUMNS, i - MIND_COLUMNS - 1]) {
    if (
      origin < 0 ||
      origin % MIND_COLUMNS >= MIND_COLUMNS - 1 ||
      origin >= MIND_SIZE - MIND_COLUMNS
    )
      continue;
    const cells = [
      origin,
      origin + 1,
      origin + MIND_COLUMNS,
      origin + MIND_COLUMNS + 1,
    ];
    if (cells.every((j) => top(b.grid[j]) && !top(b.grid[j]).sever))
      return cells;
  }
  return [];
}
export function cardEffects(c) {
  return {
    ...cards[c.id].effects,
    ...(c.upgrade ? cards[c.id].upgrade?.effects : {}),
  };
}
export function insightGain(b, c, i) {
  const f = cardEffects(c);
  return (f.insight || 0) + (f.adjInsight || 0) * gridNeighbors(b, i).length;
}
export function equipmentHealAmount(item, inventory) {
  const d = items[item.id];
  return (
    (d.effect.heal || 0) +
    (d.effect.heal &&
    d.synergy &&
    d.synergy === inventory.find((x) => x.uid === item.gem)?.id
      ? 1
      : 0)
  );
}
function normalizeEquipmentHealing(state) {
  if (state.battle && !state.battle.healUses) {
    // Older saves did not track triggers. Do not grant more healing by reloading.
    state.battle.healUses = {};
    for (const uid of Object.values(state.equipment || {})) {
      const item = state.inventory.find((x) => x.uid === uid);
      if (items[item?.id]?.effect.heal)
        state.battle.healUses[uid] = Math.min(
          state.battle.turn || 0,
          items[item.id].healLimit || 2,
        );
    }
  }
  if (state.checkpoint) normalizeEquipmentHealing(state.checkpoint);
}
export function cardPower(b, c, i) {
  const d = cards[c.id],
    f = cardEffects(c);
  let n = f.hpDamage
    ? c.hp
    : f.damage
      ? f.damage + (c.upgrade ? d.upgrade?.bonus || 0 : 0)
      : 0;
  if (f.row)
    n += b.grid.reduce(
      (sum, slot, j) =>
        sum +
        (j !== i &&
        Math.floor(j / MIND_COLUMNS) === Math.floor(i / MIND_COLUMNS) &&
        top(slot)?.element === c.element &&
        !top(slot).sever &&
        !c.sever
          ? f.row
          : 0),
      0,
    );
  if (f.adj) n += gridNeighbors(b, i).length * f.adj;
  if (f.matchingDamage) n += matchingNeighbors(b, c, i) * f.matchingDamage;
  if (f.square && squarePattern(b, c, i).length) n *= 2;
  const level = b.grid[i].findIndex((x) => x.uid === c.uid) + 1;
  for (let j = 0; j < b.grid.length; j++)
    if (j !== i) {
      const tower = top(b.grid[j]);
      if (tower?.magnified && b.grid[j].length === level) n *= 2;
    }
  return corruptionPower(b, i, n);
}

// Resolve elemental damage locally; only unmodified base damage travels onward.
// A surviving weakness bonus may travel only to a defender with the same weakness.
export function allyHit(hit, element, hp, swallow = false) {
  const base = hit.damage;
  const weak = hit.element !== "Arcane" && cycle[hit.element] === element;
  const resistant =
    !weak && element !== "Arcane" && cycle[element] === hit.element;
  const bonus = weak
    ? hit.weaknessElement === element
      ? (hit.weaknessBonus ?? 0)
      : Math.ceil(base / 2)
    : 0;
  const damage = weak ? base + bonus : resistant ? Math.ceil(base / 2) : base;
  const absorbed = Math.min(hp, damage);
  const remaining = swallow
    ? 0
    : weak
      ? Math.max(0, base - Math.max(0, hp - bonus))
      : resistant
        ? Math.min(base, Math.max(0, damage - hp) * 2)
        : Math.max(0, base - hp);
  return {
    damage,
    absorbed,
    remaining,
    weaknessBonus: weak && !swallow ? Math.max(0, bonus - hp) : 0,
    weaknessElement: weak && !swallow ? element : null,
  };
}
export function incomingDamageText(hit) {
  return `${hit.damage} ${hit.element} base damage remaining${hit.stage === "ally" && hit.weaknessBonus ? ` + ${hit.weaknessBonus} weakness bonus against ${hit.weaknessElement}` : ""}`;
}
export function defenseRate(def, attack) {
  return elementalRate(def, attack);
}
export function blockHit(block, element, damage, attack) {
  const rate = defenseRate(element, attack),
    effective = Math.ceil(block * rate),
    stopped = Math.min(effective, damage);
  return {
    remaining: damage - stopped,
    block: Math.floor((effective - stopped) / rate),
  };
}
export function adjacent(i) {
  return [
    i % MIND_COLUMNS ? i - 1 : -1,
    i % MIND_COLUMNS < MIND_COLUMNS - 1 ? i + 1 : -1,
    i >= MIND_COLUMNS ? i - MIND_COLUMNS : -1,
    i < MIND_SIZE - MIND_COLUMNS ? i + MIND_COLUMNS : -1,
  ].filter((x) => x >= 0);
}
export const corner = (i) =>
  [0, MIND_COLUMNS - 1, MIND_SIZE - MIND_COLUMNS, MIND_SIZE - 1].includes(i);
const top = (slot) => slot?.at(-1),
  blankStatus = () => ({ burn: 0, poison: 0, corrode: 0 }),
  clamp = (n, a, b) => Math.max(a, Math.min(b, n));
export function cardAllowance(b, c, i) {
  const d = cards[c.id];
  if (d.singleUse) return Math.max(0, 1 - c.used);
  if (d.limit < 0) return Infinity;
  const plus = b.grid.some(
    (x, j) =>
      cards[top(x)?.id]?.keystone &&
      corner(j) &&
      (j % MIND_COLUMNS === i % MIND_COLUMNS ||
        Math.floor(j / MIND_COLUMNS) === Math.floor(i / MIND_COLUMNS)),
  )
    ? 1
    : 0;
  return Math.max(0, d.limit + plus - c.used);
}
// Value recoverable damage/defense across the whole stack, including covered cards.
// Charged damage is one eventual release, never multiplied by lifetime activations.
export function stackValue(b, i) {
  const slot = b.grid[i];
  const power = [...slot].reverse().reduce((sum, c) => {
    const d = cards[c.id],
      f = d.effects,
      allowance = cardAllowance(b, c, i);
    const usable =
      allowance > 0 && (!d.charge || allowance >= chargeActivations(b, c, i));
    let damage = usable
      ? f.randomDamage
        ? (1 + f.randomDamage) / 2
        : cardPower(b, c, i)
      : 0;
    if (
      f.prism &&
      ["Fire", "Earth", "Wind", "Water"].every((el) =>
        gridNeighbors(b, i).some((j) => top(b.grid[j]).element === el),
      )
    )
      damage *= 4;
    if (f.all) damage *= b.enemies.filter((e) => e.hp > 0).length;
    const bonus = c.upgrade ? d.upgrade?.bonus || 0 : 0;
    const shield =
      allowance > 0 && f.shield
        ? f.shield +
          bonus +
          (f.matchingShield || 0) * matchingNeighbors(b, c, i)
        : 0;
    const storedShield = b.shields
      .filter((x) => x.owner === c.uid)
      .reduce((n, x) => n + x.block, 0);
    const ward = Math.max(
      c.ward || 0,
      allowance > 0 && f.ward ? f.ward + bonus : 0,
    );
    return (
      sum +
      Math.max(damage, shield, storedShield, ward, d.type === "Ally" ? c.hp : 0)
    );
  }, 0);
  return {
    power,
    focus: b.grid[i].reduce(
      (n, c) => n + (cards[c.id].focus === 99 ? 0 : cards[c.id].focus),
      0,
    ),
    activations: b.grid[i].reduce((n, c) => n + cardAllowance(b, c, i), 0),
  };
}
// Owned instances, including equipped gear, keep their identity through exchanges.
export function tradeAssets(s, trade) {
  const isItem = trade.kind === "item",
    defs = isItem ? items : cards;
  return (isItem ? s.inventory : s.deck)
    .filter((x) => {
      const d = defs[x.id];
      return (
        (!trade.id || trade.id === x.id) &&
        (!trade.slot || trade.slot === d.slot) &&
        (!trade.type || trade.type === d.type) &&
        (!trade.rarity || trade.rarity === d.rarity)
      );
    })
    .map((x) => {
      const d = defs[x.id],
        socketed = isItem && s.inventory.some((y) => y.gem === x.uid);
      const reason =
        d.cursed || (!isItem && d.type === "Hex")
          ? "Cannot trade a Curse or Hex"
          : socketed
            ? "Remove this Gem at a Tavern before trading it"
            : null;
      return {
        ...x,
        eligible: !reason,
        reason,
        equippedSlot: isItem
          ? Object.keys(s.equipment).find((k) => s.equipment[k] === x.uid) ||
            null
          : null,
      };
    });
}
export function gridTargets(b, t) {
  const occupied = b.grid
    .map((slot, i) => ({ slot, i, c: top(slot) }))
    .filter((x) => x.c);
  let targets = [];
  if (t.grid === "row" || t.grid === "column") {
    const col = t.grid === "column",
      count = col ? MIND_COLUMNS : MIND_ROWS;
    let best = 0,
      max = -1;
    for (let k = 0; k < count; k++) {
      const n = occupied
        .filter((x) =>
          col ? x.i % MIND_COLUMNS === k : Math.floor(x.i / MIND_COLUMNS) === k,
        )
        .reduce((n, x) => n + x.slot.length, 0);
      if (n > max) {
        max = n;
        best = k;
      }
    }
    targets = occupied.filter((x) =>
      col
        ? x.i % MIND_COLUMNS === best
        : Math.floor(x.i / MIND_COLUMNS) === best,
    );
  } else if (t.target === "valuable") {
    const valued = occupied.map((x) => ({ ...x, value: stackValue(b, x.i) }));
    targets = valued
      .sort(
        (a, z) =>
          z.value.power - a.value.power ||
          z.value.focus - a.value.focus ||
          (z.value.activations === a.value.activations
            ? 0
            : z.value.activations > a.value.activations
              ? 1
              : -1) ||
          a.i - z.i,
      )
      .slice(0, t.count || 1);
  } else {
    const score = (x) =>
      t.target === "newest"
        ? -x.c.placed
        : t.target === "oldest"
          ? x.c.placed
          : t.target === "tallest"
            ? -x.slot.length
            : t.target === "connected"
              ? -gridNeighbors(b, x.i).length
              : x.i;
    targets = occupied
      .sort((a, z) => score(a) - score(z) || a.i - z.i)
      .slice(0, t.count || 1);
  }
  return targets.map((x) => x.i);
}

// Expand older 5×4 saves by coordinates, preserving complete stacks and block owners.
export function normalizeMindGrid(state) {
  const b = state.battle;
  if (b) {
    if (b.grid.length === 20 && (!b.columns || b.columns === 5)) {
      const remap = (i) => Math.floor(i / 5) * MIND_COLUMNS + (i % 5);
      const expanded = Array.from({ length: MIND_SIZE }, () => []);
      b.grid.forEach((stack, i) => {
        expanded[remap(i)] = stack;
      });
      b.grid = expanded;
      for (const portion of b.shields || []) portion.slot = remap(portion.slot);
    } else if (b.grid.length !== MIND_SIZE) {
      throw Error("Unsupported Mind Grid dimensions in save");
    }
    b.columns = MIND_COLUMNS;
    b.rows = MIND_ROWS;
  }
  if (state.checkpoint) normalizeMindGrid(state.checkpoint);
}

function bypassOpeningCorruption(b, e, d, t) {
  return (
    b?.enemyFirst &&
    b.turn === 0 &&
    e.cycle === 0 &&
    d.openingCorruption &&
    t.applyCorruption
  );
}
function normalizeLoomRotations(s) {
  for (const e of s.battle?.enemies || []) {
    const d = enemies[e.id];
    if (e.id === "mendingTutor") {
      e.name = d.name;
      e.tier = d.tier;
    }
    if (e.id === "mendingWarden") {
      if (JSON.stringify(e.rotation) !== JSON.stringify(d.rotation)) {
        // Honor any already visible warning before beginning the new rotation.
        const pending = e.corruptionPlan?.[0]?.kind;
        const at = ["nausea", "anger", "hole"].indexOf(pending);
        e.cycle = pending ? Math.max(0, at) * 2 + 1 : 0;
        e.rotation = clone(d.rotation);
        delete e.openingCorruption;
      }
      e.signature = d.signature;
      e.counter = d.counter;
      e.corruptionCap = d.corruptionCap;
    }
    if (d?.stratum !== 2 || d.tutorialOnly) continue;
    const old = e.rotation;
    if (old?.length && JSON.stringify(old) !== JSON.stringify(d.rotation)) {
      const t = old[e.cycle % old.length];
      let next = d.rotation.findIndex((r) => r.name === t.name);
      if (next < 0 && t.applyCorruption)
        next = d.rotation.findIndex((r) => r.applyCorruption);
      else if (next < 0 && t.markCorruption)
        next = d.rotation.findIndex(
          (r) => r.markCorruption === t.markCorruption,
        );
      e.cycle =
        Math.floor(e.cycle / old.length) * d.rotation.length +
        Math.max(0, next);
      e.rotation = clone(d.rotation);
    }
    e.corruptionCap = d.corruptionCap;
  }
  if (s.checkpoint) normalizeLoomRotations(s.checkpoint);
  if (s.tutorial?.finalStart?.battle)
    normalizeLoomRotations({ battle: s.tutorial.finalStart.battle });
}

function normalizeLoomRoster(s) {
  const map = {
    seamstress: "blackBile",
    censer: "bombadier",
    borrowedChoir: "trickster",
  };
  if ((s.stratum || 1) === 2 && map[s.archon]) {
    s.archon = map[s.archon];
    if (map[s.revealedArchon]) s.revealedArchon = map[s.revealedArchon];
    for (const e of s.field?.entities || [])
      if (e.type === "Archon" && map[e.enemy]) e.enemy = map[e.enemy];
    // Already-started legacy boss battles retain their identity and boss reward.
  }
  if (s.checkpoint) normalizeLoomRoster(s.checkpoint);
}
function normalizeInitialWards(s) {
  for (const c of s.battle?.grid.flat() || [])
    if (
      cards[c.id]?.type === "Ward" &&
      c.ward === 0 &&
      !c.zeroWard &&
      !c.mending &&
      c.used === 0
    )
      c.ward = 1;
  if (s.checkpoint) normalizeInitialWards(s.checkpoint);
}

