import { cards } from "./content.mjs";
import { CORRUPTIONS } from "./strata.mjs";
const top = (stack) => stack.at(-1);
const neighbors = (i) =>
  [i % 7 ? i - 1 : -1, i % 7 < 6 ? i + 1 : -1, i - 7, i + 7].filter(
    (j) => j >= 0 && j < 42,
  );
export function corruptionAt(b, i) {
  return b.corruptions?.[i] || null;
}
export function canMend(c, corruption) {
  return !!corruption && !!CORRUPTIONS[corruption.kind];
}
export function canEnter(b, c, i) {
  const q = corruptionAt(b, i);
  if (top(b.grid[i])?.mending) return false;
  if (c.id === "elves") return !b.grid[i].length;
  return q?.kind !== "hole";
}
export function corruptionPower(b, i, power) {
  return neighbors(i).some(
    (j) => corruptionAt(b, j)?.kind === "nausea" && !b.grid[j].length,
  )
    ? Math.floor(power / 2)
    : power;
}
export function resetCoveredInsanity(b) {
  for (const [i, q] of Object.entries(b.corruptions || {}))
    if (q.kind === "insanity" && b.grid[i].length) q.value = 1;
}
// Stable, deliberately simple value: the card's printed damage/Guard strength.
// Utility cards score zero; ties follow row-major order, then normal target order.
export function angerChoice(g, slot) {
  const b = g.s.battle;
  if (b.channel < 1 || b.grid[slot].length) return null;
  const phase = b.phase,
    channel = b.channel;
  let choices;
  try {
    b.phase = "activate";
    b.channel = Number.MAX_SAFE_INTEGER;
    choices = g.baseLegal().filter((a) => {
      const c = a.type === "activate" && top(b.grid[a.slot]);
      return c && neighbors(slot).includes(a.slot) && a.element === c.element;
    });
  } finally {
    b.phase = phase;
    b.channel = channel;
  }
  const value = (a) => {
    const c = top(b.grid[a.slot]),
      d = cards[c.id],
      f = d.effects;
    const printed = Math.max(
      f.damage || 0,
      f.randomDamage || 0,
      f.hpDamage ? d.hp || 0 : 0,
      f.shield || 0,
      f.ward || 0,
    );
    return printed + (printed && c.upgrade ? d.upgrade?.bonus || 0 : 0);
  };
  return (
    choices.sort((a, z) => value(a) - value(z) || a.slot - z.slot)[0] || null
  );
}
export function triggerAnger(g, slot) {
  const b = g.s.battle,
    q = b.corruptions?.[slot];
  if (q?.kind !== "anger" || q.triggeredTurn === b.turn) return;
  q.triggeredTurn = b.turn;
  const a = angerChoice(g, slot);
  if (!a) return;
  const c = top(b.grid[a.slot]);
  g.log(
    `Anger forces ${cards[c.id].name} without Attunement, spending 1 Channel and its activation allowance.`,
  );
  g.present("corruption", { slot, name: "Anger · forced activation" });
  (g.s.stats.angerActivations ||= []).push({
    turn: b.turn,
    corruptionSlot: slot,
    slot: a.slot,
    card: c.uid,
    element: a.element,
  });
  g.activate(a, { channelCost: 1, deferPump: true });
}
export function prepareCorruption(g, e, t) {
  const b = g.s.battle;
  b.corruptions ||= {};
  const existing = Object.values(b.corruptions).filter(
    (q) => q.source === e.uid && !(e.id === "bombadier" && q.kind === "mine"),
  ).length;
  let room = (e.corruptionCap || 1) - existing;
  e.corruptionPlan = [];
  const kinds = [
    ...Array(t.count || 1).fill(t.markCorruption),
    ...(t.alsoCorruption ? Array(t.alsoCount || 1).fill(t.alsoCorruption) : []),
  ];
  for (const kind of kinds) {
    // Bombadier reserves a separate mine pool so accumulated Holes and Anger cannot
    // silently cancel the promised late-cycle three-bomb cast.
    if (!(e.id === "bombadier" && kind === "mine") && room-- <= 0) break;
    if (
      kind === "mine" &&
      e.mineCap &&
      Object.values(b.corruptions).filter(
        (q) => q.source === e.uid && q.kind === "mine",
      ).length +
        e.corruptionPlan.filter((p) => p.kind === "mine").length >=
        e.mineCap
    )
      continue;
    let candidates = b.grid.flatMap((stack, i) => {
      if (
        b.corruptions[i] ||
        b.enemies.some(
          (enemy) =>
            enemy.hp > 0 && enemy.corruptionPlan?.some((p) => p.slot === i),
        )
      )
        return [];
      const c = top(stack),
        d = cards[c?.id],
        f = d?.effects;
      if (kind === "hole" && stack.length) return [];
      if (
        kind === "hypnosis" &&
        (!c ||
          g.allowance(c, i) <= 0 ||
          !(f.damage || f.hpDamage || f.shield || f.ward || f.randomDamage))
      )
        return [];
      return [i];
    });
    if (!candidates.length) continue;
    const score = (i) => {
      const c = top(b.grid[i]);
      if (kind === "hypnosis")
        return (
          g.cardPower(c, i) + (cards[c.id].effects.ward || g.shieldPower(c, i))
        );
      const adjacent = neighbors(i).filter((j) => b.grid[j].length).length;
      if (t.spread && e.corruptionPlan.length) {
        const distance = Math.min(
          ...e.corruptionPlan.map(
            (p) =>
              Math.abs((i % 7) - (p.slot % 7)) +
              Math.abs(Math.floor(i / 7) - Math.floor(p.slot / 7)),
          ),
        );
        return distance * 10 + adjacent;
      }
      // Empty spaces beside the most cards threaten useful formations.
      return (c ? 0 : 100) + adjacent * 10;
    };
    const best = Math.max(...candidates.map(score));
    candidates = candidates.filter((i) => score(i) === best);
    // Seeded, committed space. Never follow a recalled/moved card.
    const slot = g.pick(candidates);
    e.corruptionPlan.push({ slot, kind });
    g.log(
      e.name +
        " marks " +
        CORRUPTIONS[kind].name +
        " at row " +
        (Math.floor(slot / 7) + 1) +
        ", column " +
        ((slot % 7) + 1) +
        ". One player turn to respond.",
    );
  }
  if (e.corruptionPlan.length)
    g.present("corruption", {
      slots: e.corruptionPlan.map((p) => p.slot),
      name: "Foretold Corruptions",
    });
}
export function applyCorruptions(g, e) {
  const b = g.s.battle;
  const applied = [];
  for (const { slot, kind } of e.corruptionPlan || []) {
    if (b.corruptions[slot] || (kind === "hole" && b.grid[slot].length)) {
      g.log(CORRUPTIONS[kind].name + " fails at its committed space.");
      continue;
    }
    b.corruptions[slot] = {
      kind,
      uid: g.uid(),
      source: e.uid,
      value: 1,
      remaining: 1,
      damage: e.mineDamage || 20,
      element: "Fire",
      createdTurn: b.turn,
    };
    g.log(CORRUPTIONS[kind].name + " corrupts a space.");
    applied.push(slot);
  }
  e.corruptionPlan = [];
  resetCoveredInsanity(b);
  if (applied.length)
    g.present("corruption", { slots: applied, name: "Corrupted spaces" });
}
export function retargetCoveredCorruptions(g, covered) {
  const b = g.s.battle;
  if (!b || !covered.length) return;
  for (const e of b.enemies.filter((e) => e.hp > 0)) {
    for (const mark of [...(e.corruptionPlan || [])]) {
      if (!covered.includes(mark.slot)) continue;
      const previous = mark.slot;
      const reserved = b.enemies.flatMap((enemy) =>
        (enemy.corruptionPlan || []).map((p) => p.slot),
      );
      let candidates = b.grid.flatMap((stack, i) => {
        if (b.corruptions[i] || reserved.includes(i)) return [];
        if (mark.kind !== "hypnosis") return stack.length ? [] : [i];
        const c = top(stack),
          f = cards[c?.id]?.effects;
        return c &&
          g.allowance(c, i) > 0 &&
          (f.damage || f.hpDamage || f.shield || f.ward || f.randomDamage)
          ? [i]
          : [];
      });
      if (mark.kind !== "hypnosis" && candidates.length) {
        const score = (i) =>
          neighbors(i).filter((j) => b.grid[j].length).length;
        const best = Math.max(...candidates.map(score));
        candidates = candidates.filter((i) => score(i) === best);
      }
      if (!candidates.length) {
        e.corruptionPlan = e.corruptionPlan.filter((p) => p !== mark);
        g.log(
          e.name +
            " cannot relocate " +
            CORRUPTIONS[mark.kind].name +
            ": no open space remains.",
        );
        continue;
      }
      mark.slot = g.pick(candidates);
      g.log(
        e.name +
          " redirects " +
          CORRUPTIONS[mark.kind].name +
          " from row " +
          (Math.floor(previous / 7) + 1) +
          ", column " +
          ((previous % 7) + 1) +
          " to row " +
          (Math.floor(mark.slot / 7) + 1) +
          ", column " +
          ((mark.slot % 7) + 1) +
          ".",
      );
      g.present("corruption", {
        slot: mark.slot,
        name: "Redirected: " + CORRUPTIONS[mark.kind].name,
      });
    }
  }
}
export function repairTargets(g, c, i) {
  if (c.mending) return [];
  const b = g.s.battle;
  return [i, ...neighbors(i)].flatMap((slot) => [
    ...(b.biles?.[slot] ? [{ cardTarget: slot, repairKind: "bile" }] : []),
    ...(canMend(c, b.corruptions?.[slot])
      ? [{ cardTarget: slot, repairKind: b.corruptions[slot].kind }]
      : []),
  ]);
}
function completeRepair(g, c, i, m) {
  const b = g.s.battle,
    layer = m.kind === "bile" ? b.biles : b.corruptions;
  if (layer?.[m.slot]?.uid !== m.corruptionUid) return false;
  delete layer[m.slot];
  (g.s.stats.repairs ||= []).push({
    stratum: g.s.stratum,
    turn: b.turn,
    slot: m.slot,
    kind: m.kind,
    card: c.uid,
  });
  g.present("corruption", {
    slot: m.slot,
    name: "Mended · " + CORRUPTIONS[m.kind].name,
  });
  g.log("Machine Elves repair " + CORRUPTIONS[m.kind].name + ".");
  if (g.allowance(c, i) <= 0) {
    b.grid[i] = b.grid[i].filter((x) => x.uid !== c.uid);
    b.discard.push({ id: c.id, uid: c.uid, upgrade: c.upgrade });
    g.log("Their final repair complete, Machine Elves return to discard.");
  }
  return true;
}
export function mend(g, c, i, target = i, kind = null) {
  const b = g.s.battle;
  const q = kind === "bile" ? b.biles?.[target] : b.corruptions?.[target];
  if (!canMend(c, q) || ![i, ...neighbors(i)].includes(target)) return;
  const delay = Math.max(
    0,
    (CORRUPTIONS[q.kind].repairTurns || 0) - (c.upgrade ? 1 : 0),
  );
  const job = {
    slot: target,
    corruptionUid: q.uid,
    kind: q.kind,
    due: b.turn + delay,
  };
  if (delay) c.mending = job;
  else completeRepair(g, c, i, job);
}
export function startRepairs(g) {
  const b = g.s.battle;
  for (const [i, stack] of b.grid.entries()) {
    const c = top(stack),
      m = c?.mending;
    if (!m || m.due > b.turn || c.freeze >= b.turn) continue;
    delete c.mending;
    // The repair is committed to a space, but must remain within reach.
    if ([i, ...neighbors(i)].includes(m.slot)) completeRepair(g, c, i, m);
  }
  resetCoveredInsanity(b);
  for (const [i, q] of Object.entries(b.corruptions || {})) {
    if (q.kind !== "insanity" || b.grid[i].length) continue;
    const loss = Math.min(g.s.hp, q.value++);
    g.s.hp -= loss;
    g.s.stats.damageTaken += loss;
    g.present("hit", {
      target: "player",
      amount: loss,
      element: "Chaos",
      name: "Insanity",
    });
    g.log("Insanity: lose " + loss + " HP.");
    if (g.s.hp <= 0) {
      g.finish(false, "Insanity");
      return;
    }
  }
}
export function corruptionRound(g) {
  const b = g.s.battle;
  resetCoveredInsanity(b);
  for (const [key, q] of Object.entries(b.corruptions || {})) {
    const i = Number(key),
      c = top(b.grid[i]);
    if (q.kind === "mine" && q.createdTurn < b.turn && --q.remaining <= 0) {
      delete b.corruptions[i];
      if (c) {
        g.destroyCard(i, c.uid);
        g.log("Mind Mine destroys its cover.");
      }
      g.present("mineExplosion", {
        slot: i,
        covered: !!c,
        name: "Mind Mine detonates",
      });
      if (!c)
        b.jobs.unshift({
          kind: "hit",
          name: "Mind Mine",
          damage: q.damage || 18,
          element: q.element || "Arcane",
          gridSourceSlot: i,
          source: q.source,
        });
    }
    if (q.kind === "hypnosis") compelCard(g, i, q);
  }
}

export function compelCard(g, i, q, forced = false) {
  const b = g.s.battle,
    c = top(b.grid[i]);
  if (
    !c ||
    c.hypnosisTurn === b.turn ||
    !g.condition(c, i) ||
    !(forced
      ? g.allowance(c, i) > 0 && !c.zeroWard && c.freeze < b.turn
      : g.activationAvailable(c, i))
  )
    return;
  const d = cards[c.id],
    f = d.effects,
    source = b.enemies.find((e) => e.uid === q.source && e.hp > 0);
  if (
    !source ||
    !(f.damage || f.hpDamage || f.randomDamage || f.shield || f.ward)
  )
    return;
  c.hypnosisTurn = b.turn;
  c.used++;
  c.lastActivatedTurn = b.turn;
  g.present("corruption", { slot: i, name: "Hypnosis · " + d.name });
  if (d.charge && c.charge < d.charge) {
    c.charge = Math.min(d.charge, c.charge + 1);
    return;
  }
  if (d.charge) c.charge = 0;
  const damage = f.randomDamage
    ? corruptionPower(b, i, 1 + Math.floor(g.rand() * f.randomDamage))
    : g.cardPower(c, i);
  if (damage)
    b.jobs.unshift({
      kind: "hit",
      name: "Hypnosis · " + d.name,
      damage,
      element: c.lastActivationElement || c.element,
      source: q.source,
      gridSourceSlot: i,
    });
  if (f.shield || f.ward)
    source.guard += f.shield
      ? g.shieldPower(c, i)
      : corruptionPower(b, i, f.ward + (c.upgrade ? d.upgrade?.bonus || 0 : 0));
  if (d.destroyAfterActivation) g.destroyCard(i, c.uid);
}

sources.loom-bosses.mjs:
import { cards, enemies } from "./content.mjs";
import { compelCard } from "./corruptions.mjs";

const top = (stack) => stack.at(-1);
const order = (a, b) => (a % 7) - (b % 7) || a - b;

// Bile has a separate space layer: it can crawl across Nausea or Hypnosis.
export function bilePlan(g, e) {
  const b = g.s.battle;
  const active = Object.keys(b.biles || {})
    .map(Number)
    .filter((i) => b.biles[i].source === e.uid)
    .sort(order);
  const edge = active.find((i) => i % 7 === 0);
  if (edge != null) return { from: edge, to: "player" };
  const eligible = (i) =>
    i >= 0 &&
    i < 42 &&
    !b.biles?.[i] &&
    top(b.grid[i]) &&
    g.allowance(top(b.grid[i]), i) > 0;
  for (const from of active) {
    const row = Math.floor(from / 7),
      col = from % 7;
    const next = [
      ...(row > 0 ? [from - 7, ...(col > 0 ? [from - 8] : [])] : []),
      ...(row < 5 ? [from + 7, ...(col > 0 ? [from + 6] : [])] : []),
    ]
      .filter(eligible)
      .sort(order);
    if (next.length) return { from, to: next[0] };
  }
  const fresh = b.grid
    .map((_, i) => i)
    .filter(eligible)
    .sort((a, z) => (z % 7) - (a % 7) || a - z);
  return fresh.length
    ? {
        from: null,
        to: fresh[0],
        ...(e.cycle >= 16 && fresh.length > 1
          ? { additional: [fresh[1]] }
          : {}),
      }
    : null;
}

export function phasePlan(b, e, axis) {
  if (e.phasePlan?.cycle === e.cycle && e.phasePlan.axis === axis)
    return e.phasePlan;
  const count = axis === "H" ? 6 : 7;
  const totals = Array.from({ length: count }, (_, line) =>
    b.grid.reduce(
      (n, stack, i) =>
        n +
        ((axis === "H" ? Math.floor(i / 7) : i % 7) === line
          ? stack.length
          : 0),
      0,
    ),
  );
  return { cycle: e.cycle, axis, line: totals.indexOf(Math.max(...totals)) };
}

export function phaseMoves(b, plan) {
  if (!plan) return [];
  return b.grid.flatMap((stack, from) => {
    if ((plan.axis === "H" ? Math.floor(from / 7) : from % 7) !== plan.line)
      return [];
    const to =
      plan.axis === "H"
        ? Math.floor(from / 7) * 7 + (((from % 7) + 2) % 7)
        : ((Math.floor(from / 7) + 2) % 6) * 7 + (from % 7);
    return [{ from, to, occupied: stack.length > 0 }];
  });
}

export function refreshBossPlans(g) {
  const b = g.s.battle;
  if (!b) return;
  for (const e of b.enemies.filter((x) => x.hp > 0)) {
    if (enemies[e.id].bile) e.bilePlan = bilePlan(g, e);
    const move =
      enemies[e.id].rotation[e.cycle % enemies[e.id].rotation.length];
    if (move.disrupt && !e.purifyPending)
      e.phasePlan = phasePlan(b, e, move.disrupt);
  }
}

export function resolveBile(g, e) {
  const p = bilePlan(g, e);
  if (!p) return;
  for (const to of [p.to, ...(p.additional || [])])
    resolveGlob(g, e, { from: p.from, to });
}
function resolveGlob(g, e, p) {
  const b = g.s.battle;
  b.biles ||= {};
  const old = p.from == null ? null : b.biles[p.from];
  if (p.from != null) delete b.biles[p.from];
  g.present("bileMove", {
    source: e.uid,
    from: p.from,
    to: p.to,
    name: "Bile",
  });
  if (p.to === "player") {
    g.applyFriendlyStatus("poison", 2, {
      source: e.uid,
      gridSourceSlot: p.from,
    });
    g.log("Bile reaches you: Poison +2. That glob disappears.");
    return;
  }
  const c = top(b.grid[p.to]);
  c.used++;
  g.present("status", {
    target: "card",
    slot: p.to,
    name: "Bile · −1 activation",
  });
  if (c.id === "elves") {
    g.log(
      "Machine Elves intercept Bile, spending one activation and removing it.",
    );
    (g.s.stats.repairs ||= []).push({
      stratum: g.s.stratum,
      turn: b.turn,
      slot: p.to,
      kind: "bile",
      card: c.uid,
    });
    if (g.allowance(c, p.to) === 0 && !c.mending) {
      b.grid[p.to].pop();
      b.discard.push({ id: c.id, uid: c.uid, upgrade: c.upgrade });
    }
  } else {
    b.biles[p.to] = old || { kind: "bile", uid: g.uid(), source: e.uid };
    g.log(
      "Bile arrives at row " +
        (Math.floor(p.to / 7) + 1) +
        ", column " +
        ((p.to % 7) + 1) +
        "; " +
        cards[c.id].name +
        " loses one activation.",
    );
  }
}

export function disrupt(g, e, plan) {
  const b = g.s.battle,
    moves = phaseMoves(b, plan);
  const stacks = moves.map((m) => ({ ...m, stack: b.grid[m.from] }));
  g.present("phaseShift", {
    source: e.uid,
    axis: plan.axis,
    name: "Phase disruption " + plan.axis,
    moves: stacks
      .filter((m) => m.stack.length)
      .map(({ from, to }) => ({ from, to })),
  });
  for (const m of stacks) b.grid[m.from] = [];
  for (const m of stacks) b.grid[m.to] = m.stack;
  // Activated Shield pools travel with their owners, never remain at old slots.
  for (const shield of b.shields) {
    const m = stacks.find((m) => m.stack.some((c) => c.uid === shield.owner));
    if (m) shield.slot = m.to;
  }
  const destroyed = new Set();
  for (const { to, stack } of stacks) {
    if (!stack.length) continue;
    const q = b.corruptions?.[to];
    if (q?.kind === "hole") {
      g.present("corruption", {
        slot: to,
        name: "Memory Hole · entire stack destroyed",
      });
      for (const c of [...stack]) {
        destroyed.add(c.uid);
        g.destroyCard(to, c.uid);
      }
    } else if (q?.kind === "hypnosis") compelCard(g, to, q, true);
  }
  b.shields = b.shields.filter((s) => !destroyed.has(s.owner));
  g.log(
    "Phase disruption " +
      plan.axis +
      ": whole stacks wrap two spaces; Corruptions stay fixed.",
  );
}

export function antiElement(g) {
  const b = g.s.battle,
    totals = {};
  const add = (element, value) => {
    if (element && element !== "Arcane" && value > 0)
      totals[element] = (totals[element] || 0) + value;
  };
  for (const shield of b.shields) {
    if (top(b.grid[shield.slot] || [])?.uid === shield.owner)
      add(shield.element, shield.block);
  }
  for (const { c } of g.activeWards()) add(c.element, c.ward);
  // Equipment refills when Enemy begins; preview that same available pool.
  if (b.phase === "enemy") {
    for (const item of b.bracelets) add(item.element, item.block);
  } else {
    for (const item of g.equipped())
      add(item.element, item.definition.effect.block || 0);
  }
  const armor = g.equipped().find((x) => x.slot === "torso");
  if (armor)
    add(armor.element, b.phase === "enemy" ? b.armorBlock : g.armorCapacity());
  const values = Object.entries(totals).sort((a, z) => z[1] - a[1]);
  if (!values.length || values[0][1] === values[1]?.[1])
    return { element: "Arcane", totals };
  const counters = {
    Fire: "Water",
    Water: "Wind",
    Wind: "Earth",
    Earth: "Fire",
    Light: "Chaos",
    Chaos: "Light",
  };
  return { element: counters[values[0][0]] || "Arcane", totals };
}

sources.policy.mjs:
import { cards, items, enemies, VERSION } from "./content.mjs";
import {
  activationGrowth,
  defensiveElement,
  offense,
  defenseRate,
  adjacent,
  allyHit,
  corner,
  enemyImmuneTo,
} from "./engine.mjs";
export const defaultWeights = {
  damage: 1,
  survival: 1.4,
  economy: 4,
  development: 1,
  progress: 1,
};
const dist = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
export class WeightedPolicy {
  constructor(weights = {}) {
    this.weights = { ...defaultWeights, ...weights };
    this.id = "weighted-druid-v2.1";
  }
  choose(o, actions) {
    if (!actions.length) return null;
    let winner = actions[0],
      best = -Infinity,
      reason = "Use an available legal choice.";
    for (const a of actions) {
      let score = -0.01,
        why = "Fallback for a legal choice with unfamiliar effects.";
      try {
        [score, why] = this.score(o, a);
        const b = o.battle,
          q = b?.corruptions?.[a.slot];
        if (a.type === "place" && b) {
          const card = b.hand.find((c) => c.uid === a.uid),
            d = cards[card?.id];
          if (["anger", "insanity", "nausea"].includes(q?.kind))
            score += q.kind === "insanity" ? 14 : 7;
          if (card?.id === "elves") {
            const spaces = [a.slot, ...adjacent(a.slot)];
            const repairs = spaces.filter(
              (i) => b.corruptions?.[i] || b.biles?.[i],
            ).length;
            score += repairs ? 8 + repairs * 3 : -12;
          }
          if (q?.kind === "mine")
            score +=
              q.remaining <= 1
                ? d?.focus === 0 || card?.id === "shield"
                  ? 18
                  : -8
                : 2;
          if (
            q?.kind === "hypnosis" &&
            (d?.effects.damage || d?.effects.shield || d?.effects.ward)
          )
            score -= 12;
          if (
            b.enemies.some((e) =>
              e.corruptionPlan?.some(
                (p) => p.slot === a.slot && p.kind === "hole",
              ),
            )
          )
            score += 10;
        }
        if (a.type === "activate" && (a.effects.mend || a.effects.stitch)) {
          const slot = a.cardTarget ?? a.slot;
          const hazard =
            a.repairKind === "bile" ? b.biles?.[slot] : b.corruptions?.[slot];
          score +=
            hazard?.kind === "mine" ? 25 : hazard?.kind === "bile" ? 22 : 18;
          why = "Repair an eligible nearby Corruption with the companion.";
        }
        if (
          a.type === "recall" &&
          q &&
          ["anger", "nausea", "insanity", "mine"].includes(q.kind)
        )
          score -= 20;
        if (a.type === "activate" && q?.kind === "hypnosis") score += 8;
        if (!Number.isFinite(score)) score = -0.01;
      } catch {}
      if (score > best) {
        best = score;
        winner = a;
        reason = why;
      }
    }
    return { action: winner, reason, score: best, policy: this.id };
  }
  cardValue(id, o) {
    const d = cards[id];
    if (!d) return 0;
    const e = d.effects;
    return (
      (e.damage || 0) / (d.charge ? d.charge + 1 : 1) +
      (d.hp || 0) * 0.6 +
      (e.ward || 0) * 0.55 +
      (e.shield || 0) * 0.4 +
      (e.channel || 0) * 6 +
      ((e.insight || 0) + 2 * (e.adjInsight || 0)) * 1.5 +
      (e.focusPermanent || 0) * 10 +
      (e.heal || 0) * 1.5 +
      (e.poison || 0) * 3 +
      (e.burn || 0) * 2 +
      (e.corrode || 0) * 6 +
      (e.hpDamage ? 8 : 0) +
      (d.growth ? 8 : e.growAfterAttack ? 4 : 0) +
      (e.conduit ? 4 : 0) -
      (d.focus - 1) * 3 -
      (d.type === "Hex" ? 40 : 0)
    );
  }
  gearValue(e = {}, o) {
    return (
      (e.channel || 0) * 20 +
      (e.focus || 0) * 14 +
      (e.insight || 0) * 6 +
      (e.block || 0) * 2 +
      (e.heal || 0) * 6 +
      (e.armor || 0) * 6 +
      (e.damage || 0) * (e.firstAttackOnly ? 3 : 4.5) +
      (e.movement || 0) * 3 +
      (e.resist ? 4 : 0) +
      (e.reflect ? 12 : 0) +
      (e.shield || 0) *
        (!o || o.deck.some((c) => cards[c.id]?.name.includes("Shield"))
          ? 4
          : 0) +
      (e.recall || 0) * 3 -
      (e.burn || 0) * 3 -
      (e.poison || 0) * 6 -
      (e.corrode || 0) * 12
    );
  }
  // Compare the actual owned instance, including benefits lost with its socket.
  // Elemental attunement is matchup-dependent, not an unconditional upgrade.
  itemValue(inst, o) {
    const d = items[inst?.id];
    if (!d) return 0;
    if (d.consumable)
      return (
        (d.consumable.heal || 0) * 0.8 +
        (d.consumable.focus || 0) * 6 +
        (d.consumable.channel || 0) * 8 +
        (d.consumable.draw || 0) * 4 +
        (d.consumable.damage || 0) * 0.8
      );
    const gem = items[o.inventory.find((x) => x.uid === inst.gem)?.id];
    return (
      this.gearValue(d.effect, o) -
      (d.cursed ? 40 : 0) +
      (gem
        ? this.gearValue(
            gem.id === "curseGem" ? { ...gem.effect, poison: 0 } : gem.effect,
            o,
          )
        : 0) +
      (gem && d.synergy === gem.id ? this.gearValue({ heal: 1 }, o) : 0)
    );
  }
  score(o, a) {
    const f = a.effects || {},
      w = this.weights,
      b = o.battle,
      injured = o.maxHp - o.hp;
    let n = 0,
      reason = a.label;
    switch (a.type) {
      case "discardItem":
        return [
          -30 -
            this.itemValue(
              o.inventory.find((x) => x.uid === a.uid),
              o,
            ),
          "Make Satchel space by discarding the least valuable loose item.",
        ];
      case "consume": {
        const reserve = 5;
        if (f.heal)
          return [
            Math.min(injured, f.heal) * w.survival - reserve,
            "Use finite healing when enough HP is missing.",
          ];
        if (f.focus) {
          const useful = b.hand.some(
            (c) =>
              cards[c.id].focus > b.focus &&
              cards[c.id].focus <= b.focus + f.focus,
          );
          return [
            useful ? 8 : -20,
            "Spend a Focus Draught only when it unlocks a placement.",
          ];
        }
        if (f.channel)
          return [
            b.channel === 0 &&
            b.grid.some((slot, i) => {
              const c = slot.at(-1);
              return (
                c &&
                c.used < cards[c.id].limit &&
                c.lastActivatedTurn !== b.turn
              );
            })
              ? 8
              : -20,
            "Restore Channel when an unused card can benefit.",
          ];
        if (f.draw)
          return [
            b.focus > 0 && b.hand.length === 0 ? 7 : -10,
            "Draw a card when placement resources would otherwise go unused.",
          ];
        if (f.damage) {
          const enemy = b.enemies.find((e) => e.uid === a.target);
          const damage = offense(f.damage, f.element, enemy.element);
          return [
            Math.min(damage, enemy.hp) * w.damage +
              (damage >= enemy.hp ? 14 : 0) -
              reserve,
            "Use the flask to finish an enemy or prevent a costly extra turn.",
          ];
        }
        return [-10, "Save the consumable."];
      }
      case "chooseClass":
      case "begin":
      case "continueReward":
        return [10, "Advance the journey."];
      case "startGem":
        return [
          f.defense ? 10 : 4,
          "Imbue the starting Bracelet for passive protection.",
        ];
      case "unequip":
        return [
          -25,
          "Keep equipped gear unless replacing it with better gear.",
        ];
      case "equip": {
        const inst = o.inventory.find((x) => x.uid === a.item),
          old = o.inventory.find((x) => x.uid === o.equipment[a.slot]);
        n =
          this.itemValue(inst, o) -
          this.itemValue(old, o) -
          (Object.values(o.equipment).includes(inst.uid)
            ? this.itemValue(inst, o)
            : 0);
        return [
          n > 0 ? 30 + n : -20,
          `Equip only for a net benefit (${n.toFixed(1)}), counting effects, sockets and curses.`,
        ];
      }
      case "move": {
        const p = { x: a.x, y: a.y };
        const targets = o.field.entities
          .filter((e) => !o.field.leftSupplies?.includes(e.uid))
          .map((e) => {
            let value =
              e.type === "Gold"
                ? e.value * 0.35
                : e.type === "Item"
                  ? items[e.item]?.consumable
                    ? items[e.item].consumable.heal && injured > 0
                      ? Math.min(5, injured) * 3 + 8
                      : this.itemValue({ id: e.item }, o) * 2
                    : 25
                  : e.type === "Event"
                    ? 20
                    : e.type === "Tavern"
                      ? o.gold >= 20
                        ? injured * 0.8 + 12
                        : 2
                      : e.enemy
                        ? enemies[e.enemy].tier === "Archon"
                          ? o.field.round > 18
                            ? 20
                            : -5
                          : enemies[e.enemy].tier === "Eidolon"
                            ? -12
                            : 9
                        : 0;
            if (e.enemy) value -= ((e.count || 1) - 1) * 5;
            const d = dist(p, e),
              old = dist(o.field, e);
            return { e, score: value / (d + 1) + (old - d) * 3 };
          });
        n = targets.length ? Math.max(...targets.map((x) => x.score)) : 0;
        for (const e of o.field.entities.filter((x) => x.enemy)) {
          if (dist(p, e) === 0) {
            n -= ((e.count || 1) - 1) * (o.hp < 30 ? 8 : 3);
            const tier = enemies[e.enemy].tier;
            n -=
              tier === "Eidolon"
                ? 12
                : tier === "Archon" && o.field.round < 18
                  ? 8
                  : 0;
          }
          if (o.hp < 20 && dist(p, e) <= 2) n -= 3;
        }
        n -= dist(p, { x: 5, y: 5 }) * 0.1;
        return [
          n,
          "Move toward useful visible encounters, favoring recovery and avoiding dangerous packs.",
        ];
      }
      case "wait":
        return [-1, "End movement when there is no better destination."];
      case "place": {
        const c = cards[f.card],
          e = c.effects,
          slot = b.grid[a.slot],
          ns = adjacent(a.slot).filter((i) => b.grid[i].length),
          existing = b.grid.flat().filter((x) => x.id === c.id).length;
        const hasOffense = b.grid.some((x) => {
          const t = x.at(-1);
          return (
            t &&
            t.used < cards[t.id].limit &&
            (cards[t.id].effects.damage || cards[t.id].effects.hpDamage)
          );
        });
        n = this.cardValue(c.id, o) * 0.5 + 2;
        if (e.focusPermanent) n += b.turn < 5 ? 12 : 2;
        if (c.growth) n += 8 + ns.length * 3;
        if (e.conduit)
          n +=
            ns.filter((i) => ["blast", "shield"].includes(b.grid[i].at(-1).id))
              .length * 2;
        if (e.growAfterAttack) n += 4 + ns.length * 1.5;
        if (e.damage && !hasOffense) n += 8;
        if (e.shield && existing) n -= 12;
        if (c.condition === "isolated") n += ns.length ? -30 : 4;
        if (c.condition === "corner" && !corner(a.slot)) n -= 30;
        if (
          c.condition &&
          ["Earth", "Fire", "Wind", "Water"].includes(c.condition) &&
          !ns.some((i) => b.grid[i].at(-1).element === c.condition)
        )
          n -= 20;
        if (e.adj) n += ns.length * 2;
        if (e.adjInsight)
          n += ns.filter((i) => !b.grid[i].at(-1).sever).length * 2;
        if (e.matchingDamage || e.matchingShield)
          n +=
            ns.filter(
              (i) => b.grid[i].at(-1).id === c.id && !b.grid[i].at(-1).sever,
            ).length * 2;
        if (c.attune)
          n += ns.some((i) => b.grid[i].at(-1).element !== "Arcane") ? 1 : 0;
        for (const i of ns) {
          const neighbor = b.grid[i].at(-1),
            def = cards[neighbor.id];
          if (def.growth) n += 3;
          else if (
            def.effects.growAfterAttack &&
            neighbor.used < def.limit &&
            neighbor.hp < def.hpCap
          )
            n += 1.5;
        }
        if (slot.length && !c.stack) n -= 50;
        if (
          c.stack === "supersede" &&
          slot.at(-1)?.used < cards[slot.at(-1).id].limit
        )
          n -= 10;
        if (c.stack === "tower" && !slot.length) n -= 6;
        return [
          n * w.development,
          "Develop usable offense, growth, and economy while preserving placement conditions.",
        ];
      }
      case "recall":
        if (b.grid[a.slot].at(-1)?.mending)
          return [-20, "Let the pending repair finish rather than canceling it."];
        return [
          f.spent && b.grid.filter((x) => x.length).length > 10 ? 3 : -15,
          "Clear exhausted cards only when grid space is scarce.",
        ];
      case "activatePhase":
      case "endTurn":
        return [-1, "Advance after worthwhile actions are used."];
      case "activate": {
        if (f.charging && f.canRelease === false)
          return [
            -2,
            "Preserve Channel: this card lacks enough uses to release.",
          ];
        const target = b.enemies.find((e) => e.uid === a.target);
        const threat = b.enemies.reduce(
          (sum, e) =>
            sum +
            (e.tell.sequence?.reduce((n, h) => n + h.damage, 0) ||
              (e.tell.damage || 0) * (e.tell.hits || 1)),
          0,
        );
        const protectedBy =
          b.grid.flat().reduce((sum, c) => sum + (c.ward || 0), 0) +
          b.shields.reduce((sum, p) => sum + p.block, 0) +
          o.bonuses.armor +
          3;
        let damage =
          f.damage || f.chargedDamage || (f.randomDamage && 6.5) || 0;
        if (f.charge > 1) damage /= f.charge;
        if (target) {
          damage = offense(damage, a.element, target.element);
          if (target.resist === a.element) damage = Math.ceil(damage / 2);
          if (target.wisp) damage *= a.element === "Arcane" ? 0.5 : 2;
          if (target.flicker) damage = 0.5;
          if (damage >= target.hp) n += 15;
          damage = Math.min(damage, target.hp);
          if (target.id === "colossus" && a.element === "Chaos") n -= 8;
        }
        if (f.all) damage *= b.enemies.length;
        n +=
          damage * w.damage +
          (target && enemyImmuneTo(target, "burn") ? 0 : (f.burn || 0) * 2) +
          (f.burnAll || (f.chargedBurnAll || 0) / (f.charge || 1)) *
            b.enemies.filter((e) => !enemyImmuneTo(e, "burn")).length *
            2 +
          (target && enemyImmuneTo(target, "poison")
            ? 0
            : (f.poison || 0) * 3) +
          (target && enemyImmuneTo(target, "corrode")
            ? 0
            : (f.corrode || 0) * 5);
        n += (f.channel || 0) > a.costs.channel ? 12 : 0;
        n += (f.focusPermanent || 0) * (b.turn < 7 ? 12 : 4);
        n += (f.insight || 0) * 0.4 + (f.focus || 0) * 1.2;
        n += Math.min(injured, f.heal || 0) * w.survival;
        if (f.cleanse)
          n += Object.values(o.status).reduce((x, y) => x + y, 0) * 2;
        if (f.shield)
          n +=
            Math.min(f.shield, Math.max(0, threat - protectedBy)) * w.survival;
        if (f.ward)
          n += Math.min(f.ward, Math.max(0, threat + 3 - protectedBy));
        if (f.taunt) n += o.hp < 15 ? 6 : 0;
        if (f.relief) n += b.turn > b.relief ? 5 : -10;
        if (f.unbind)
          n +=
            b.grid.flat().filter((x) => x.lock || x.sever || x.freeze).length *
            4;
        if (f.allyHeal) n += 4;
        if (f.conduit) {
          const c = b.grid[a.slot].at(-1);
          const supported =
            b.channel > a.costs.channel
              ? adjacent(a.slot).filter((i) => {
                  const x = b.grid[i].at(-1);
                  return (
                    x &&
                    !c.sever &&
                    !x.sever &&
                    ["blast", "shield"].includes(x.id) &&
                    x.used < cards[x.id].limit &&
                    x.lastActivatedTurn !== b.turn
                  );
                }).length
              : 0;
          const protection = b.enemies.reduce((sum, e) => {
            const hit = { damage: e.tell.damage || 0, element: e.tell.element };
            return (
              sum +
              allyHit(hit, c.element, c.hp).remaining -
              allyHit(hit, a.element, c.hp).remaining
            );
          }, 0);
          n += (supported ? 4 + supported : -2) + protection * w.survival;
        }
        if (f.growAfterAttack && target && !target.flicker)
          n += activationGrowth(b, b.grid[a.slot].at(-1), a.slot) * 0.6;
        if (f.magnify) n += 3;
        if (f.shift || f.transmute) n -= 4;
        return [
          n,
          "Balance immediate kills, incoming damage, healing, and future resources.",
        ];
      }
      case "ward":
        return [
          Math.min(f.ward, b.reaction.damage) * w.survival + (f.column + 1) * 2,
          "Absorb damage while preserving defenders closer to the player.",
        ];
      case "block":
      case "bracelet":
        return [
          Math.min(
            b.reaction.damage,
            f.block * defenseRate(f.element, b.reaction.element),
          ) *
            w.survival +
            ((f.column ?? -1) + 1) * 2,
          "Use the portion with the strongest effective Guard against this element.",
        ];
      case "armor":
        return [
          Math.min(b.reaction.damage, f.reflect ? b.reaction.damage : f.armor) *
            w.survival,
          "Choose armor protection for this hit, or preserve reflection by skipping it.",
        ];
      case "intercept": {
        const c = b.grid[a.slot].at(-1),
          d = cards[c.id],
          result = allyHit(b.reaction, defensiveElement(b, c), c.hp, f.swallow);
        return [
          (b.reaction.damage - result.remaining) * w.survival -
            (d.growth || (d.effects.growAfterAttack && c.used < d.limit)
              ? 8
              : 0) -
            (d.effects.heal ? 5 : 0) +
            (f.swallow ? b.reaction.damage : 0) +
            ((f.column ?? 0) + 1) * 2,
          "Protect player HP while retaining valuable growing Allies when possible.",
        ];
      }
      case "skipEquipment":
        return [
          -b.reaction.damage * w.survival,
          "Preserve item Guard by accepting the remaining hit; prefer absorbing damage when possible.",
        ];
      case "takeHit":
        return [
          b.bracelets.reduce((n, p) => n + p.block, 0) +
            o.bonuses.armor -
            (o.hp < 20 ? 10 : 0),
          "Pass grid defenders and choose equipment protection.",
        ];
      case "rewardCard":
        return [
          this.cardValue(a.id, o) - (o.deck.length > 20 ? 6 : 0),
          "Choose a card by its damage, defense, economy, and growth features.",
        ];
      case "usePickup":
        return [
          Math.min(injured, f.heal) * w.survival + 8,
          "Drink visible healing now when injured, without needing a Satchel slot.",
        ];
      case "leaveItem":
        return [0, "Leave an unwanted item without accepting its effects."];
      case "skipReward":
        return [0, "Skip a card that would dilute the deck."];
      case "rewardGem":
      case "rewardSetting":
        return [
          this.gearValue(f.gear, o),
          "Prefer permanent economy and passive protection.",
        ];
      case "takeItem":
      case "buy": {
        const id = f.item,
          d = id?.startsWith("card:") ? null : items[id];
        n = d
          ? this.itemValue({ id }, o) + (d.slot === "gem" ? 3 : 0)
          : this.cardValue(id?.slice(5), o);
        if (a.type === "buy") n -= a.price * 0.13;
        if (o.satchel?.used >= o.satchel?.capacity && d) {
          const loose = o.inventory.filter(
            (x) =>
              !Object.values(o.equipment).includes(x.uid) &&
              !o.inventory.some((g) => g.gem === x.uid) &&
              !items[x.id].cursed,
          );
          if (loose.length)
            n -= Math.min(...loose.map((x) => this.itemValue(x, o)));
        }
        return [
          n,
          "Value the offered item against its price, Satchel space and risk.",
        ];
      }
      case "heal":
        return [injured * 0.9, "Recover HP before the next encounter."];
      case "eventChoice":
        return [
          (f.heal ? Math.min(injured, f.heal) * 1.4 : 0) +
            (f.gold || 0) * 0.2 +
            (f.hp || 0) * 1.5 +
            (f.card ? this.cardValue(f.card, o) : 0) +
            (f.hex ? -30 : 0) +
            (f.item ? this.itemValue({ id: f.item }, o) : 0) +
            (f.clean || f.cleanHex
              ? o.deck.filter((x) => cards[x.id].type === "Hex").length * 20
              : 0) -
            (a.costs.gold || 0) * 0.2 -
            (a.tradeItem != null
              ? this.itemValue(
                  o.inventory.find((x) => x.uid === a.tradeItem),
                  o,
                )
              : 0) -
            (a.tradeCard != null
              ? this.cardValue(o.deck.find((x) => x.uid === a.tradeCard).id, o)
              : 0),
          "Compare the visible reward with the cost of the specific offered item or card.",
        ];
      case "socket": {
        const inst = o.inventory.find((x) => x.uid === a.uid),
          old = o.inventory.find((x) => x.uid === inst.gem),
          g = o.inventory.find((x) => x.uid === a.gem);
        return [
          this.itemValue({ ...inst, gem: g.uid }, o) -
            this.itemValue(inst, o) +
            (g.id === "curseGem" ? 6 : 0) -
            (old?.id === "curseGem" ? 6 : 0) +
            (old ? -10 : 10),
          "Socket unused Gems to activate their powers.",
        ];
      }
      case "upgrade":
        return [
          8 - (a.costs.gold || 0) * 0.06 - (a.costs.hp || 0) * 0.7,
          "Improve a card when the cost is affordable.",
        ];
      case "removeHex": {
        const lostCard = o.deck.find((c) => c.uid === a.sacrificeCard);
        const lostItem = o.inventory.find((x) => x.uid === a.sacrificeItem);
        const hpCost = a.costs.hp || 0;
        return [
          25 -
            hpCost * (o.hp < 25 ? 2 : 0.8) -
            (a.costs.gold || 0) * 0.06 -
            (lostCard ? this.cardValue(lostCard.id, o) : 0) -
            (lostItem ? this.itemValue(lostItem, o) : 0),
          "Weigh Hex relief against the displayed HP, Gold, or sacrifice cost.",
        ];
      }
      case "sell":
        return [
          f.cursed ? 10 : -30,
          "Keep useful equipment; pay to remove a Curse.",
        ];
      case "gossip":
        return [
          !o.archon && o.gold > 100 ? 2 : -5,
          "Buy Archon information only with surplus Gold.",
        ];
      case "giveTraveler":
        return [-5, "Keep Gold for survival; this gift offers no known material benefit."];
      case "declineTraveler":
        return [0.1, "Politely decline the request before continuing."];
      case "leave":
        return [0, "Continue when useful services are exhausted."];
      case "replaceArmor":
        return [
          this.gearValue(f.gear, o) -
            this.itemValue(
              o.inventory.find((x) => x.uid === a.old),
              o,
            ),
          "Replace Armor only for a better evaluated effect.",
        ];
      case "declineArmor":
        return [0, "Respect the three-Armor carry limit."];
      case "remove":
      case "unsocket":
        return [-20, "Avoid unnecessary deck removal or socket churn."];
      default:
        return [
          Object.values(f)
            .filter((x) => typeof x === "number")
            .reduce((a, b) => a + b, 0) * 0.01,
          "Fallback: choose a legal action using available public effects.",
        ];
    }
  }
}

sources.death.mjs:
import { enemies, enemyDeathLines } from "./content.mjs";
const statusNames = { burn: "burning", poison: "poison", corrode: "corrosion" };
const closing = "Another traveler may find a different way.";
// Capture the actual lethal hit before reaction/status cleanup. Do not guess an
// enemy from an attack name: several enemies can share a move name.
export function describeDeath(state, cause = "", hit = null) {
  const enemy =
    !hit?.statusHit && hit?.source != null
      ? state.battle?.enemies.find((e) => e.uid === hit.source)
      : null;
  let detail;
  if (hit?.statusHit || (!hit && statusNames[cause])) {
    const status = hit?.name || cause;
    detail = {
      kind: "status",
      status,
      summary: `You died from ${statusNames[status] || status || "an ongoing status"}.`,
    };
  } else if (enemy) {
    const tier = enemy.tier || enemies[enemy.id]?.tier;
    detail = {
      kind: "enemy",
      enemyId: enemy.id,
      enemyUid: enemy.uid,
      enemyName: enemy.name,
      tier,
      attack: hit.name || cause || "an attack",
      flavor: ["Archon", "Eidolon"].includes(tier)
        ? enemyDeathLines[enemy.id] || ""
        : "",
    };
    detail.summary = `${detail.enemyName} killed you with ${detail.attack}.`;
  } else {
    detail = {
      kind:
        state.mode === "event"
          ? "event"
          : cause === "Burning Itch"
            ? "hex"
            : "other",
      cause,
      summary: cause
        ? `You died ${state.mode === "event" ? "during" : "from"} ${cause}.`
        : "Your journey ended here.",
    };
  }
  return {
    ...detail,
    message: [detail.flavor, detail.summary, closing].filter(Boolean).join(" "),
  };
}
export const deathSummary = (result) =>
  result.death?.summary || describeDeath({}, result.cause).summary;
export const deathMessage = (result) =>
  result.death?.message || describeDeath({}, result.cause).message;

sources.tutorial.mjs:
import { loomGuide, loomActions, loomAfter } from "./loom-tutorial.mjs";
import { cards, items, enemies, DRUID_COMPANION_STORY } from "./content.mjs";
export const TUTORIAL = {
  id: "stratum1",
  version: 11,
  name: "The First Clearing",
  seed: 11001,
};
const steps = [];
const note = (id, title, text, focus = "", setup = null) =>
  steps.push({ id, title, text, focus, setup, kind: "note" });
const action = (
  id,
  title,
  text,
  match,
  focus = "",
  gesture = null,
  setup = null,
) =>
  steps.push({ id, title, text, match, focus, gesture, setup, kind: "action" });
const ui = (id, title, text, control, focus) =>
  steps.push({ id, title, text, control, focus, kind: "ui" });
const place = (id, card, slot, text, gesture = null) =>
  action(
    id,
    "Placement · " + cards[card].name,
    text,
    { type: "place", card, slot },
    "",
    gesture,
  );
const activate = (id, slot, text, element) =>
  action(id, "Activation", text, {
    type: "activate",
    slot,
    ...(element ? { element } : {}),
  });
const phase = (id) =>
  action(
    id,
    "Advance to Activation",
    "Your placement is finished. Press the arrow from Placement to Activation. Focus returns next round; this phase uses Channel.",
    { type: "activatePhase" },
  );
const end = (
  id,
  text = "Press the arrow to Enemy. Watch the Tell resolve before making your defense choice.",
) => action(id, "Let the enemy act", text, { type: "endTurn" });
const defend = (id, type, slot, text) =>
  action(id, "Choose your defense", text, {
    type,
    ...(slot == null ? {} : { slot }),
  });
const move = (id, x, y, text) =>
  action(id, "Follow the path", text, { type: "move", x, y });
const reward = (id, card, text) =>
  action(id, "Choose your reward", text, { type: "rewardCard", id: card });
const back = (id) =>
  action(
    id,
    "Back to the Clearing",
    "Return to the overworld. Your cards recover their allowances between battles.",
    { type: "continueReward" },
  );
note(
  "welcome",
  "The First Clearing",
  DRUID_COMPANION_STORY +
    "\n\nYour journey begins in the First Clearing. Read each glowing callout, then click Continue. You can pause or return to Start at any time.",
  ".field",
  "gold",
);
note(
  "gold",
  "A glint among the leaves",
  "Gold has appeared to your right. The eight arrow buttons move one space in the direction they point. Diagonal moves cost one space too.",
  ".direction-pad",
);
move("gold-move", 6, 5, "Click the glowing east arrow to move onto the Gold.");
note(
  "gold-gained",
  "Gold collected",
  "Your Gold increased by 200. These coins will pay for Tavern upgrades later. Gold left on the Field depletes over time, so collect it quickly! Ordinary journeys offer smaller, variable caches.",
  "header .gold",
  "ring",
);
move("item-move", 7, 5, "An item has appeared one space east. Move to it.");
action(
  "ring-take",
  "An item is yours to inspect",
  "Take the Rootbound Ring. In ordinary journeys you may leave an item behind.",
  { type: "takeItem", index: 0 },
);
ui(
  "inventory-open",
  "Your belongings",
  "Click Inventory in the top-right corner of the screen. Items you wear appear in Equipped; everything else stays in the Satchel.",
  "inventory",
  '[data-ui="inventory"]',
);
action(
  "ring-equip",
  "Equip the Ring",
  "Drag the Rootbound Ring from the Satchel to your right finger. You may also inspect it and choose Equip. It adds a separate 2-damage hit to your first attack each turn.",
  { type: "equip", itemId: "ring", slot: "finger2" },
  '.satchel, [data-equip-slot="finger2"]',
);
note(
  "gear-ready",
  "Ready for the road",
  "The Ring is now Equipped, not in the Satchel. During player movement you can equip and unequip items. Gems are different: socket them only at a Tavern.",
  '[data-equip-slot="finger2"]',
  "mote",
);
move(
  "mote-move",
  8,
  5,
  "A Mosswing waits to the east. The arrow moves directly onto it. Clicking the enemy itself normally opens its details.",
);
note(
  "reveal",
  "Insight reveals your choices",
  "Watch the four cards dealt from your Grimoire. Insight starts at 4 and falls to 0 as Reveal finishes. It controls how many cards you see, not how many you may place.",
  ".resources > span:nth-child(1), .hand",
);
ui(
  "grimoire-open",
  "Your Grimoire",
  "Open the Grimoire in the top-right corner of the screen to see your deck. Undrawn cards remain there; discarded cards recycle when it empties.",
  "grimoire",
  '[data-ui="grimoire"]',
);
note(
  "focus",
  "Focus places cards",
  "Focus starts at 1. This Shield costs 1 Focus to place. Drag it from your revealed hand to the outlined space; the card stays there between rounds.",
  ".resources > span:nth-child(2), .hand",
);
place(
  "shield-place",
  "shield",
  18,
  "Drag a Shield onto the outlined space. Keyboard: focus the Shield, press Enter, close its details, then Enter on the marked space.",
  "drag-place",
);
note(
  "focus-empty",
  "Focus is spent",
  "Focus is now 0, so no more cost-1 cards can be placed. Do not worry: it returns to 1 next round. The phase arrows move only forward.",
  ".resources > span:nth-child(2)",
);
phase("first-phase");
note(
  "tell3",
  "Read the Tell",
  "Mosswing is about to deal 3 Arcane damage. A Shield activation costs 1 Channel and creates 4 Guard for this turn. Keep an eye on two numbers: Channel (2 each round) pays for activations this round; the card's activation limit is its total uses across rounds before Recall or the next battle restores it.",
  ".enemy .tell, .resources > span:nth-child(3)",
);
activate(
  "shield-activate",
  18,
  "Click Activate on your Shield to prepare 4 Guard.",
);
end("first-enemy");
defend(
  "shield-block3",
  "block",
  18,
  "Click your glowing Shield to absorb the 3-damage attack.",
);
note(
  "shield-expiry",
  "The card stays; its Guard expires",
  "The attack was absorbed. Unused Shield Guard disappears at round end, but the card remains. Activate it again to make fresh Guard. This Shield has one use left; keep an eye on Channel and each card's allowance.",
  '[data-slot="18"], .resources',
);
place(
  "blast-place",
  "blast",
  22,
  "Place a Blast on the outlined space. Your refreshed Focus pays for it.",
);
phase("second-phase");
activate(
  "second-shield",
  18,
  "Prepare the Shield again. The next enemy attack deals 5, so its 4 Guard will need help from your Bracelet.",
);
activate(
  "first-blast",
  22,
  "You began with 2 Channel. The Shield used 1, leaving 1 to activate Blast. Drag Blast onto Mosswing, or double-click its Activate button to hit the top enemy. Blast deals 4; your Ring adds a separate 2.",
);
end("second-enemy");
defend(
  "shield-block5",
  "block",
  18,
  "Click Shield: it stops 4 of the 5 damage. The remaining attack continues toward you.",
);
defend(
  "bracelet-block1",
  "bracelet",
  null,
  "Click your right Bracelet. It absorbs the last 1 damage without spending Channel. Its 2 Guard refills each enemy round.",
);
place(
  "synergy-place",
  "blast",
  23,
  "Place a second Blast immediately beside the first, on the outlined space.",
);
note(
  "synergy",
  "Neighbors can change a card",
  "The connecting line shows a real interaction. Each adjacent Blast adds +1 damage, so each now shows 5. Inspect card details to learn which neighbors, patterns and stacks matter.",
  '[data-slot="22"], [data-slot="23"]',
);
phase("third-phase");
activate(
  "synergy-kill",
  23,
  "Activate the new Blast against Mosswing. Its 5 damage and the Ring's first-hit 2 will finish this fight.",
);
reward(
  "ward-reward",
  "ward",
  "Choose Ward. This reward goes into your Grimoire, and we will use it in the next fight.",
);
back("first-back");
note(
  "pursuit",
  "An item beyond your reach",
  "An item lies northeast, but a Rootling is approaching. You have 2 movement points. Take both steps before the Rootling gets its movement turn.",
  ".field, .direction-pad",
  "pursuit",
);
move(
  "pursuit-move",
  9,
  4,
  "Take your first northeast step toward the distant item. You will still have 1 movement point; the Rootling waits.",
);
note(
  "pursuit-one-left",
  "One more step is yours",
  "You moved 1 space and have 1 movement point left. The Rootling has not moved. You may move up to 2 spaces before enemies take their turn.",
  ".field, .direction-pad, .section-head .muted",
);
move(
  "pursuit-second",
  10,
  3,
  "Take your second northeast step. Movement reaches 0; now watch the Rootling move one space at a time onto you.",
);
note(
  "caught",
  "Enemies move too",
  "The Rootling landed on you during enemy movement, so it acts first, before you reveal or place any cards. Your Bracelet can still defend. Moving onto an enemy yourself lets you take the first turn.",
  ".enemy",
);
defend(
  "ambush-bracelet",
  "bracelet",
  null,
  "Use your Bracelet against the Rootling's opening 3-damage attack. It absorbs 2; the remaining 1 reaches you. Then your first Reveal begins.",
);
place(
  "ward-place",
  "ward",
  18,
  "Place Ward in the marked space nearer to you. It starts with 1 ward value. If you spend that last point defending, it becomes Depleted and cannot activate. Isolated means it needs empty neighboring spaces to activate.",
);
phase("ward-phase");
activate(
  "ward-activate",
  18,
  "Activate Ward to add 10 to its starting 1: it now stores 11. Unlike Shield, that stock will persist across rounds.",
);
end("ward-enemy");
defend("ward-block", "ward", 18, "Choose Ward to absorb the 3-damage attack.");
note(
  "ward-persists",
  "8 Ward remains",
  "Ward kept its remaining 8 ward value into this round. You do not have to activate it every turn. Depleted: fully depleted wards cannot activate.",
  '[data-slot="18"]',
);
place(
  "sapling-place",
  "sapling",
  19,
  "Place Sapling in column 6, directly beside Ward in column 5. Allies have HP, can attack, and may intercept incoming attacks.",
);
phase("sapling-phase");
activate(
  "sapling-attack",
  19,
  "Activate Sapling to attack with its current 4 HP; your Ring adds 2. After attacking, Sapling gains 1 HP per adjacent card, capped at 10. Ward is adjacent, so Sapling grows to 5 HP after this attack. It can still defend after attacking.",
);
end(
  "rootling-rest",
  "Rootling spends this move Gathering Strength. Advance and use the breathing room to prepare your defense.",
);
place(
  "route-shield",
  "shield",
  20,
  "Place Shield in column 7, beside Sapling in column 6. Ward, Sapling and Shield now form an adjacent line, with Sapling in the middle.",
);
phase("route-phase");
activate(
  "route-shield-activate",
  20,
  "Double-click Shield's activation to use it without attunement. This creates 4 Guard on the right, before the attack reaches Sapling and Ward.",
);
activate(
  "route-sapling-attack",
  19,
  "Sapling attacks for its current 5 HP, then grows by 2 beside Ward and Shield, reaching 7 HP. Its attack allowance is spent, but its HP can still absorb attacks.",
);
note(
  "route",
  "Defend from right to left",
  "Rootling is winding up a 30-damage attack. Choose Shield, then Sapling, then Ward, then Bracelet. Once the attack passes a column, cards farther right cannot defend it. In normal play you may skip a defense or click your Druid to take the hit.",
  '.enemy .tell, [data-slot="19"], [data-slot="20"], [data-slot="18"]',
);
end("route-enemy");
defend(
  "route-block",
  "block",
  20,
  "Click Shield first. Its 4 Guard absorbs 4 of the 30 damage; 26 continue toward Sapling.",
);
defend(
  "route-ally",
  "intercept",
  19,
  "Click Sapling. Its 7 HP absorb 7 damage. It dies and enters Destroyed until the next battle. The remaining 19 continue leftward to Ward.",
);
defend(
  "route-ward",
  "ward",
  18,
  "Click Ward. Its stored 8 ward value absorbs 8, leaving 11 damage.",
);
defend(
  "route-bracelet",
  "bracelet",
  null,
  "Click your Bracelet. It stops 2, then the final 9 automatically reach the Druid because no defenses remain.",
);
note(
  "route-done",
  "Every layer matters",
  "You took only 9 of the original 30 damage. Each hit showed the actual HP or Guard lost. Warning: attacks will NEVER move backwards toward the right side, so choose the order of your defending cards wisely!",
  ".battle-player, header .hp",
);
note(
  "recall-intro",
  "Bring a card back",
  "The Rootling is recovering. Your Shield survived with a use left, but you can Recall it now. Recall happens during Placement and spends the card's listed Focus cost. Most Allies cannot Recall unless their text allows it.",
  '[data-slot="20"], .resources > span:nth-child(2)',
);
action(
  "recall-shield",
  "Recall the Shield",
  "Click the Shield's name to open its full details, then click Recall. This Shield costs 1 Focus to Recall. It leaves the grid and goes to Discard, not directly into your hand.",
  { type: "recall", slot: 20 },
);
note(
  "recall-discard",
  "Waiting in Discard",
  "Your Shield is now in Discard and Focus is 0. When the remaining Grimoire is drawn, Discard recycles into it. You can draw the Shield again during this battle, and placing it again restores its activation allowance.",
  '[data-ui="piles"], .resources > span:nth-child(2)',
);
ui(
  "recall-piles",
  "Inspect the piles",
  "Open the Grimoire / Discard / Destroyed button at the bottom left. Find the recalled Shield in Discard and the defeated Sapling in Destroyed.",
  "piles",
  '[data-ui="piles"]',
);
note(
  "discard-destroyed",
  "Discard returns; Destroyed waits",
  "Discard can recycle during this battle. Destroyed cannot: your Sapling is unavailable for the rest of this fight. More powerful enemies can send cards to Destroyed, too. Don't worry: after battle, those cards return safely to your Grimoire.",
  "#modal",
);
note(
  "recall-protection",
  "A little foresight",
  "Recall can save an important card before a dangerous enemy move. It still takes time to draw it again. Destroyed is temporary; a card permanently removed or sacrificed by an Event is different and does not return.",
  '[data-ui="piles"]',
);
phase("recall-phase");
end(
  "recall-enemy",
  "The Rootling spends this turn recovering. Advance to Enemy. Your Focus will refill for next round's placement.",
);
place(
  "rootling-blast",
  "blast",
  22,
  "Place Blast on the marked space to finish the weakened Rootling.",
);
phase("rootling-phase");
activate(
  "rootling-kill",
  22,
  "Blast and your Ring deal the remaining 6 damage. Destroyed Allies will be available again next battle.",
);
reward(
  "water-reward",
  "water",
  "Take Water Blast. It will help with the upcoming lesson about elements.",
);
back("rootling-back");
note(
  "gem-road",
  "Return to the item",
  "The next movement turn has begun. You have 2 movement points again, and the item is only 1 space north. Landing on an encounter or pickup ends your movement, even if a point remains.",
  ".field",
  "gem-road",
);
move(
  "gem-move",
  10,
  2,
  "Move north onto the item using your first step of this turn.",
);
note(
  "movement-forfeit",
  "Stopping costs the remaining movement",
  "You used only 1 step to reach this item, but movement is now 0: the remaining point was forfeited. Landing on a pickup or encounter ends your movement for that turn. Finish this pickup before the next movement turn begins.",
  ".catalog, .tutorial-movement",
);
action(
  "gem-take",
  "A Sapphire",
  "Take the Sapphire. Gems imbue Settings such as Bracelets and Rings; they are not worn by themselves.",
  { type: "takeItem", index: 0 },
);
note(
  "gem-save",
  "Save it for the Tavern",
  "You may equip ordinary items during map movement, but Gems may be socketed or removed only at a Tavern. We will save this Sapphire for your Bracelet.",
  '[data-ui="inventory"]',
);
note(
  "consumables",
  "Supplies along the path",
  "Three bottles now line the northern edge in the northeast corner. Ordinary Strata scatter three supplies in seeded random places, including Healing Sap. They do not decay. Take a detour when useful, or leave them for later. Your Satchel holds 12 loose items; equipped gear and socketed Gems take no space.",
  ".field",
  "supply-route",
);
move(
  "supplies-approach",
  10,
  1,
  "Move north toward the three bottles in the corner. You have one more step before the round ends.",
);
move(
  "healing-road",
  10,
  0,
  "Move north onto the Healing Sap. Entering a supply space ends your movement, just like other pickups.",
);
action(
  "healing-pickup",
  "Collect or drink",
  "Collect Healing Sap for the Satchel. When injured you can also Drink now directly from a pickup, even with a full Satchel. Leave it here preserves these visible supplies for a later visit.",
  { type: "takeItem", index: 0 },
);
action(
  "consume-healing",
  "Drink Healing Sap",
  "Use Healing Sap in the tray to restore 5 HP. It costs no Channel, but the bottle is gone permanently, including in later battles. On the map you may use one healing consumable per movement round.",
  { type: "consume", itemId: "healingSap" },
  ".consumable-tray",
);
move(
  "insight-road",
  9,
  0,
  "Move west to the blue Insight Dew. We will save this bottle for battle.",
);
action(
  "insight-pickup",
  "Keep an extra draw",
  "Collect Insight Dew. Each bottle takes one Satchel slot; this one draws a card immediately during Placement.",
  { type: "takeItem", index: 0 },
);
move("focus-road", 8, 0, "Move west to the golden Focus Draught.");
action(
