export function tutorialReward(g) {
  if (g.s.tutorial?.id === "stratum2") {
    g.s.tutorial.completed = true;
    g.finish(true, "The Mending Ground complete");
    return true;
  }
  const t = g.s.tutorial;
  if (!t) return false;
  if (t.fight === 4) {
    t.completed = true;
    g.finish(true, "The First Clearing complete");
    return true;
  }
  g.s.reward = {
    cards: t.fight === 1 ? ["ward"] : t.fight === 2 ? ["water"] : null,
    gem: false,
    setting: false,
    boss: false,
  };
  return false;
}
